def _guard_when(pre_state, write_call):
    args = write_call.get('arguments') or {}
    pb_id = args.get('platform_booking_id')
    pb = (pre_state.get('platform_bookings') or {}).get(pb_id) or {}
    vendor_id = pb.get('vendor_id')
    if vendor_id != 'V-IR':
        return False
    vendor = (pre_state.get('vendors') or {}).get(vendor_id) or {}
    tdr_late_min = (vendor.get('fare_rules') or {}).get('tdr_late_min', 0)
    vb_id = pb.get('vendor_booking_id')
    vb = (pre_state.get('vendor_bookings') or {}).get(str(vendor_id) + '|' + str(vb_id)) or {}
    data = vb.get('data') or {}
    delay_min = data.get('delay_min', 0)
    train = data.get('train')
    date = data.get('date')
    for se in (pre_state.get('status_events') or {}).values():
        if se.get('vendor_id') == vendor_id and se.get('service_id') == train and (se.get('service_date') == date):
            se_data = se.get('data') or {}
            if se_data.get('delay_min') is not None:
                delay_min = se_data.get('delay_min')
    if delay_min <= tdr_late_min:
        return False
    actual_dep = data.get('actual_departure')
    for se in (pre_state.get('status_events') or {}).values():
        if se.get('vendor_id') == vendor_id and se.get('service_id') == train and (se.get('service_date') == date):
            se_data = se.get('data') or {}
            if se_data.get('expected_departure'):
                actual_dep = se_data.get('expected_departure')
    if not actual_dep:
        return False
    filed_before = False
    for vt in (pre_state.get('vendor_threads') or {}).values():
        if vt.get('platform_booking_id') == pb_id and vt.get('request_type') == 'tdr_filing':
            sent_at = vt.get('sent_at')
            if sent_at and to_minutes(sent_at) < to_minutes(actual_dep):
                filed_before = True
    return not filed_before


