def _guard_then(pre_state, write_call, post_state):
    args = write_call.get('arguments') or {}
    vendor_id = args.get('vendor_id')
    loc = args.get('record_locator')
    key = str(vendor_id) + '|' + str(loc)
    vb_before = (pre_state.get('vendor_bookings') or {}).get(key) or {}
    vb_after = (post_state.get('vendor_bookings') or {}).get(key) or {}
    if vb_after == vb_before:
        return True
    data_before = vb_before.get('data') or {}
    fare_class = data_before.get('fare_class')
    if fare_class not in ('Classic', 'Extra'):
        return True
    vendor = (pre_state.get('vendors') or {}).get(vendor_id) or {}
    rule = (vendor.get('fare_rules') or {}).get(fare_class) or {}
    pb = (pre_state.get('platform_bookings') or {}).get(vb_before.get('platform_booking_id')) or {}
    dep = data_before.get('dep')
    for s in data_before.get('segments') or []:
        dep = s.get('dep')
    now = pre_state.get('_now') or ((pre_state.get('meta') or {}).get('now') or {}).get('value')
    before_dep = True if not dep or not now else to_minutes(now) < to_minutes(dep)
    if write_call.get('name') == 'flight_change':
        inv = (pre_state.get('inventory') or {}).get(str(vendor_id) + '|' + str(args.get('new_flight'))) or {}
        change_fee = float(rule.get('change_fee') or 0.0)
        fare_diff = max(0.0, float(inv.get('fare_difference') or 0.0))
        expected = change_fee + fare_diff
        pre_charges = pre_state.get('charges') or {}
        post_charges = post_state.get('charges') or {}
        added = sum((float((post_charges.get(k) or {}).get('amount') or 0.0) for k in post_charges if k not in pre_charges))
        return abs(added - expected) < 0.01
    if write_call.get('name') == 'flight_cancel':
        canc = (vb_after.get('data') or {}).get('cancellation') or {}
        rem = float(canc.get('remaining_value') or 0.0)
        if not before_dep:
            return abs(rem - 0.0) < 0.01
        total = float(pb.get('total') or 0.0)
        fee = float(rule.get('cancel_fee') or 0.0)
        expected = max(0.0, total - fee)
        return abs(rem - expected) < 0.01
    return True


