            expected_forfeit = total * share
            expected_rem = total - expected_forfeit
        return abs((canc.get('forfeit') or 0.0) - expected_forfeit) < 0.01 and abs((canc.get('remaining_value') or 0.0) - expected_rem) < 0.01 and (canc.get('returned_as') == rule.get('refund_form'))
