    canc = data.get('cancellation') or {}
    ce = (pb.get('details') or {}).get('cancel_event') or {}
    if ce.get('by') in ('vendor', 'airline'):
        max_ref = total
    elif canc:
        max_ref = canc.get('remaining_value') or 0.0
    elif vb.get('status') == 'no_show' or (dep and now_min >= to_minutes(dep)):
        max_ref = 0.0
    else:
        share = rule.get('cancel_forfeit_share') or 0.0
