    args = write_call.get('arguments') or {}
    vid = args.get('vendor_id')
    rl = args.get('record_locator')
    new_vid = args.get('new_vendor_id')
    if new_vid == vid:
        return True
    v = (pre_state.get('vendors') or {}).get(vid) or {}
    roc = (v.get('fare_rules') or {}).get('reroute_other_carrier') or {}
    partners = roc.get('partners') or []
