prelude:
_YES = ("yes", "yeah", "yep", "confirm", "confirmed", "sure", "ok", "okay", "correct", "proceed")
_YES_PHRASES = ("go ahead", "please do", "that is right", "that's right")
_NO = ("no", "not", "never", "nope", "nah", "cannot", "cant", "dont", "stop", "wait", "wrong", "incorrect")

def _plain_words(text):
    return set("".join(c if (c.isalnum() or c.isspace()) else " " for c in text).split())

def user_confirmed(transcript):
    """True when the last user turn says yes to an action an assistant turn proposed (D43 case 3)."""
    messages = list(transcript or [])
    last = None
    for pos in range(len(messages) - 1, -1, -1):
        if messages[pos].get("role") == "user":
            last = pos
            break
    if last is None:
        return False
    proposal = ""
    for msg in reversed(messages[:last]):
        if msg.get("role") == "assistant" and (msg.get("content") or "").strip():
            proposal = msg.get("content") or ""
            break
    if "?" not in proposal:
        return False  # nothing was proposed, so nothing was confirmed
    text = (messages[last].get("content") or "").lower()
    words = _plain_words(text)
    if words & set(_NO) or "n't" in text:
        return False  # a refusal that happens to carry a yes word is still a refusal
    return bool(words & set(_YES)) or any(phrase in text for phrase in _YES_PHRASES)

def called_before(transcript, *names):
    """True when the transcript already holds a tool call with one of these names."""
    wanted = set(names)
    for msg in list(transcript or []):
        for call in msg.get("tool_calls") or []:
            if call.get("name") in wanted:
                return True
    return False

def said_before(transcript, *needles):
    """True when an assistant turn already contains one of these strings, case-insensitive."""
    for msg in list(transcript or []):
        if msg.get("role") != "assistant":
            continue
        text = (msg.get("content") or "").lower()
        if any(needle.lower() in text for needle in needles):
            return True
    return False


_YES_OPEN = ("yes", "yeah", "yep", "sure", "ok", "okay", "confirm", "confirmed", "go ahead", "please do", "correct")
_NO_OPEN = ("no", "nope", "don't", "dont", "do not", "not yet", "hold on", "wait", "stop")
_CONJUNCTIONS = ("and", "but", "so", "then", "well", "oh", "ah", "um")
_CONSENT = ("go ahead", "proceed", "i confirm", "you have my ok", "you have my okay", "you have my consent",
            "you have my permission", "you have my approval", "i agree", "i approve", "i authorize", "i authorise",
            "please do it", "please do that", "please do this")


def _opening_word(text, words):
    for word in words:
        if text.startswith(word) and (len(text) == len(word) or not text[len(word)].isalnum()):
            return word
    return ""


def _opens_on(text, words):
    return _opening_word(text, words) != ""


def _openings(text):
    for mark in "*_`~":
        text = text.replace(mark, "")
    for end in "!?\n":
        text = text.replace(end, ".")
    out = []
    for part in text.lower().split("."):
        part = part.strip()
        part = part[len(_opening_word(part, _CONJUNCTIONS)):].strip(" ,\t")
        if part:
            out.append(part)
    return out


def _says_yes(text):
    low = text.lower()
    return any(_opens_on(o, _YES_OPEN) for o in _openings(text)) or any(p in low for p in _CONSENT)


def user_confirmed(transcript):
    users = [(turn.get("content") or "") for turn in transcript or [] if turn.get("role") == "user"]
    if not users:
        return False
    last = _openings(users[-1])
    # The reply's answer comes first: a later sentence opening on no answers another question once it said yes.
    if last and _opens_on(last[0], _NO_OPEN):
        return False
    if not _says_yes(users[-1]) and any(_opens_on(o, _NO_OPEN) for o in last):
        return False
    return any(_says_yes(text) for text in users)


def to_minutes(ts):
    """Minutes since 1970-01-01T00:00Z of an ISO date or time with an optional offset ("2026-10-29T12:00:00-04:00")."""
    ts = str(ts)
    y, m, d = int(ts[0:4]), int(ts[5:7]), int(ts[8:10])
    hour, minute = (int(ts[11:13]), int(ts[14:16])) if len(ts) >= 16 else (0, 0)
    offset = 0
    if len(ts) > 19 and ts[-6] in "+-":
        offset = (1 if ts[-6] == "+" else -1) * (int(ts[-5:-3]) * 60 + int(ts[-2:]))
    yy = y - (m <= 2)
    era = yy // 400
    yoe = yy - era * 400
    doy = (153 * ((m + 9) % 12) + 2) // 5 + d - 1
    days = era * 146097 + yoe * 365 + yoe // 4 - yoe // 100 + doy - 719468
    return days * 1440 + hour * 60 + minute - offset
